using UnityEngine;using UnityEngine.AI;using UnityEditor;using System.IO;using System.Collections.Generic;
[InitializeOnLoad]public static class NoiseGhostSurvey{
 static NoiseGhostSurvey(){EditorApplication.delayCall+=()=>{if(!File.Exists("Temp/noise_ghost_survey.request")||EditorApplication.isPlaying)return;File.Delete("Temp/noise_ghost_survey.request");var lines=new List<string>();var tri=NavMesh.CalculateTriangulation();lines.Add("nav vertices="+tri.vertices.Length+" triangles="+tri.indices.Length/3);var red=GameObject.Find("Door_Red");lines.Add("red="+red.transform.position+" forward="+red.transform.forward);var model=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/NoiseGhost/Art/FunnyCuteGhost.fbx");foreach(var r in model.GetComponentsInChildren<Renderer>()){lines.Add(r.name+" bounds="+r.bounds);foreach(var m in r.sharedMaterials)lines.Add("material="+m.name+" color="+m.color);}
 foreach(var p in new[]{new Vector3(-5.1f,0,5.5f),new Vector3(-1.5f,0,5.5f),new Vector3(-17,0,-1),new Vector3(17,0,1),new Vector3(-9.8f,0,4.3f)}){bool ok=NavMesh.SamplePosition(p,out var hit,2,NavMesh.AllAreas);lines.Add("sample "+p+" => "+ok+" "+hit.position);}File.WriteAllLines("Temp/noise_ghost_survey.txt",lines);};}
}
